const v = $input.first().json.body;
if (!v || !Array.isArray(v.candidatas) || v.candidatas.length > 50 || !v.criterios || !Array.isArray(v.verificacoes_requeridas)) throw new Error('Pedido inválido');
for (const k of ['pedido_id','execucao_id','lote_id']) if (!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(v[k])) throw new Error('Identidade inválida');
v.evidencias = []; v.pendencias = [];
return [{json:v}];

const v=$input.first().json, c=v.criterios;
for (const e of v.candidatas) {
 const id=e.google_place_id||('cnpj:'+e.cnpj), b=e.dados_brutos||{}, fonte=e.link_maps||b.link||'coleta_google';
 const ev=(criterio,opcao,estado,motivo)=>v.evidencias.push({candidata:id,criterio,opcao:String(opcao),estado,motivo,fonte,horario:new Date().toISOString()});
 for(const [k,campo] of [['nota','review_rating'],['avaliacoes','review_count']]) if(c[k]!==null) {
  const raw=b[campo]; const n=raw!==undefined&&raw!==null&&String(raw).trim()!==''?Number(raw):NaN;
  ev(k,c[k],Number.isFinite(n)?(n>=c[k]?'aprovado':'reprovado'):'nao_confirmado',Number.isFinite(n)?'Valor publicado no Google.':'Valor não confirmado pela origem.');
 }
 if(c.situacao&&c.situacao!=='priorizar_funcionamento') {
  const s=String(e.situacao_google||b.status||'').toLowerCase();
  const aberto=['operational','open','em funcionamento'].includes(s), temp=['temporarily_closed','temporarily closed'].includes(s), encerrado=['permanently_closed','permanently closed','closed_permanently'].includes(s);
  const conhecido=aberto||temp||encerrado;
  const ok=c.situacao==='excluir_encerradas'?!encerrado:aberto;
  ev('situacao',c.situacao,conhecido?(ok?'aprovado':'reprovado'):'nao_confirmado','Situação informada pela origem Google.');
 }
}
return [{json:v}];

const v=$input.first().json, c=v.criterios;
for(const e of v.candidatas) {
 const id=e.google_place_id||('cnpj:'+e.cnpj), b=e.dados_brutos||{};
 const ev=(criterio,opcao,estado,motivo)=>v.evidencias.push({candidata:id,criterio,opcao,estado,motivo,fonte:e.site||e.link_maps||'coleta_google',horario:new Date().toISOString()});
 for(const k of ['site','email']) if(c[k].length===1) {
  const opcao=c[k][0], valor=e[k];
  let presente=k==='email'?/^[^\s@]+@[^\s@]+$/.test(String(valor||'')):false;
  if(k==='site'&&valor) { try {const u=new URL(valor); presente=['http:','https:'].includes(u.protocol)&&!/(^|\.)(instagram|facebook|linkedin|google|whatsapp)\.(com|net)$/i.test(u.hostname)} catch {} }
  const confirmado=presente||b[k+'_verificado']===true;
  if(confirmado) ev(k,opcao,(opcao==='com')===presente?'aprovado':'reprovado','Presença comercial conferida na fonte.');
  else v.pendencias.push({candidata:id,criterio:k,opcao});
 }
 for(const k of ['produtos','excluir','observacoes']) if(c[k]) v.pendencias.push({candidata:id,criterio:k,opcao:c[k]});
 for(const opcao of c.tipos) v.pendencias.push({candidata:id,criterio:'tipos',opcao});
 if(c.atendimento&&c.atendimento!=='priorizar_fisica') v.pendencias.push({candidata:id,criterio:'atendimento',opcao:c.atendimento});
}
if(v.pendencias.length&&!$env.GOOGLE_QUALIFICADOR_URL) throw new Error('Qualificação selecionada ainda não configurada. Preserve o lote.');
return [{json:v}];

const v=$('Preparar presença e perfil').first().json, r=$input.first().json;
for(const k of ['pedido_id','execucao_id','lote_id','revisao','snapshot_sha256']) if(r[k]!==v[k]) throw new Error('Resposta de qualificação divergente');
if(!Array.isArray(r.evidencias)) throw new Error('Qualificação sem evidências');
v.evidencias.push(...r.evidencias);
return [{json:v}];

const v=$input.first().json;
v.numeros_whatsapp=[];
if(v.verificacoes_requeridas.includes('whatsapp')) for(const e of v.candidatas) {
 if(/^[0-9]{10,11}$/.test(e.telefone||'')) v.numeros_whatsapp.push('55'+e.telefone);
 else v.evidencias.push({candidata:e.google_place_id||('cnpj:'+e.cnpj),criterio:'telefone',opcao:'whatsapp',estado:'reprovado',motivo:'Número não informado ou sem formato válido na coleta.',fonte:'coleta_google',horario:new Date().toISOString()});
}
if(v.numeros_whatsapp.length&&(!$env.EVOLUTION_API_URL||!$env.EVOLUTION_API_KEY||!$env.EVOLUTION_INSTANCE_NAME)) throw new Error('WhatsApp selecionado ainda não configurado. Preserve o lote.');
return [{json:v}];

const v=$('Preparar WhatsApp').first().json;
const respostas=$input.all().flatMap(i=>Array.isArray(i.json)?i.json:[i.json]);
if(!respostas.length||respostas.some(r=>typeof r.exists!=='boolean'||typeof r.number!=='string')) throw new Error('Resposta WhatsApp não confirmada');
for(const e of v.candidatas) if(/^[0-9]{10,11}$/.test(e.telefone||'')) {
 const r=respostas.find(r=>r.number.replace(/\D/g,'')==='55'+e.telefone);
 v.evidencias.push({candidata:e.google_place_id||('cnpj:'+e.cnpj),criterio:'telefone',opcao:'whatsapp',contato:e.telefone,estado:r?(r.exists?'aprovado':'reprovado'):'nao_confirmado',motivo:r?'Consulta de registro no WhatsApp.':'Número sem confirmação no retorno.',fonte:'evolution_api',horario:new Date().toISOString()});
}
return [{json:v}];

const v=$input.first().json;
for(const e of v.candidatas) v.evidencias.push({candidata:e.google_place_id||('cnpj:'+e.cnpj),criterio:'telefone',opcao:'fixo',contato:e.telefone||'',estado:/^[0-9]{2}[2-5][0-9]{7}$/.test(e.telefone||'')?'aprovado':'reprovado',motivo:'Formato de telefone fixo brasileiro conferido.',fonte:'coleta_google',horario:new Date().toISOString()});
return [{json:v}];
